<script setup lang="ts">
import {onMounted,ref,watch} from 'vue'
import AppModal from '@/components/AppModal.vue'
import {demoMode} from '@/services/quality'
import {officineService,supportPermissionLabels,type SupportAssignment} from '@/services/officine'
const ending=ref<SupportAssignment|null>(null);const endReason=ref('')
async function end(){busy.value=true;dialogError.value='';try{await officineService.endAssignment(officeId.value,ending.value!,endReason.value);ending.value=null;await list()}catch(e){dialogError.value=(e as Error).message}finally{busy.value=false}}
const loading=ref(true);const busy=ref(false);const error=ref('');const dialogError=ref('');const notice=ref('');const open=ref(false)
const offices=ref<{id:number;name:string}[]>([]);const staff=ref<{id:number;name:string}[]>([]);const officeId=ref(0);const assignments=ref<SupportAssignment[]>([])
const form=ref({user_id:0,scope:'Accompagnement qualité',permissions:['officine.read'],starts_on:'',ends_on:'',request_key:''})
async function list(){if(!officeId.value)return;loading.value=true;error.value='';assignments.value=[];try{assignments.value=await officineService.proposals(officeId.value)}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
onMounted(async()=>{if(demoMode){loading.value=false;return}try{const d=await officineService.directory();offices.value=d.officines;staff.value=d.staff;officeId.value=d.officines[0]?.id||0}catch(e){error.value=(e as Error).message}finally{loading.value=false}})
watch(officeId,()=>{open.value=false;list()})
function repropose(a:SupportAssignment){create();form.value={user_id:a.user_id,scope:a.scope,permissions:[...a.permissions],starts_on:a.starts_on,ends_on:a.ends_on,request_key:crypto.randomUUID()}}
function create(){form.value={user_id:staff.value[0]?.id||0,scope:'Accompagnement qualité',permissions:['officine.read'],starts_on:new Date().toISOString().slice(0,10),ends_on:'',request_key:crypto.randomUUID()};dialogError.value='';open.value=true}
async function save(){busy.value=true;dialogError.value='';try{await officineService.propose(officeId.value,form.value);open.value=false;notice.value='Proposition enregistrée. Aucun accès avant l’approbation de l’officine. Notification préparée ; consultez son état de livraison.';await list()}catch(e){dialogError.value=(e as Error).message}finally{busy.value=false}}
const labels={pending:'À approuver',approved:'Approuvé',refused:'Refusé',revoked:'Retiré',changes_requested:'Modification demandée'}
</script>
<template><section class="page erp-page"><div class="page-heading compact"><div><p class="eyebrow">MODULE 01 · COORDINATION</p><h1>Affectations des accompagnateurs</h1><RouterLink to="/beg/demandes-accompagnement" class="text-link">Guichet des demandes d’accompagnement · M2</RouterLink><p class="page-subtitle">Proposer une portée et une période ; l’officine décide.</p></div><button v-if="!demoMode&&!error&&officeId" class="button primary" @click="create">Proposer un accompagnateur</button></div><div v-if="demoMode" class="panel form-body"><p>En démo, utilisez le sélecteur de point de vue sur l’écran Accompagnateurs.</p><RouterLink to="/dashboard/accompagnateurs" class="button primary">Ouvrir la démonstration</RouterLink></div><template v-else><p v-if="error" class="alert error" role="alert">{{error}}</p><p v-if="notice" class="alert success" role="status">{{notice}}</p><label v-if="offices.length" class="application-selector">Officine<select aria-label="Officine" v-model="officeId" :disabled="busy"><option v-for="o in offices" :key="o.id" :value="o.id">{{o.name}}</option></select></label><p v-if="loading" role="status">Chargement…</p><div v-else-if="!error" class="panel"><div class="table-scroll"><table><thead><tr><th>ACCOMPAGNATEUR</th><th>PÉRIMÈTRE</th><th>PERMISSIONS</th><th>PÉRIODE</th><th>ÉTAT</th><th>ACTION</th></tr></thead><tbody><tr v-for="a in assignments" :key="a.id"><td>{{a.name}}<span class="table-subtitle">#{{a.id}} · v{{a.version}}</span></td><td>{{a.scope}}</td><td><div v-for="p in a.permissions" :key="p">{{supportPermissionLabels[p]||p}}</div></td><td>{{a.starts_on}} → {{a.ends_on}}</td><td><span class="status-badge" :class="a.status">{{a.expired?'Proposition expirée':labels[a.status]}}</span></td><td><button v-if="a.expired||['changes_requested','refused','revoked'].includes(a.status)" class="button secondary small" @click="repropose(a)">Préparer une nouvelle proposition</button><button v-if="['approved','pending'].includes(a.status)" class="button secondary small" @click="ending=a;endReason='';dialogError=''">Terminer l’accès</button></td></tr><tr v-if="!assignments.length"><td colspan="5" class="empty-state">Aucune affectation pour cette officine.</td></tr></tbody></table></div><div class="panel-foot">Métadonnées d’affectation uniquement. Aucun accès métier automatique pour la coordination.</div></div></template>
<AppModal v-model="open" title="Proposer un accompagnateur" :busy="busy" size="wide"><form id="api-proposal" class="form-body form-grid" @submit.prevent="save"><p v-if="dialogError" class="alert error span-2" role="alert">{{dialogError}}</p><label>Accompagnateur éligible<select aria-label="Accompagnateur éligible" v-model="form.user_id" required><option :value="0" disabled>Choisir</option><option v-for="u in staff" :key="u.id" :value="u.id">{{u.name}}</option></select></label><label>Périmètre<input v-model="form.scope" required maxlength="150"/></label><label>Début<input v-model="form.starts_on" type="date" required/></label><label>Fin<input v-model="form.ends_on" type="date" :min="form.starts_on" required/></label><fieldset class="permissions-fieldset span-2"><legend>Permissions proposées</legend><label v-for="(label,key) in supportPermissionLabels" :key="key" class="checkbox-label"><input v-model="form.permissions" type="checkbox" :value="key"/>{{label}}</label></fieldset><p class="module-disclaimer span-2">L’entreprise ne peut pas approuver sa propre proposition au nom de l’officine. Les permissions de contribution concernent uniquement les missions approuvées ; aucun droit Stock ou qualité en écriture.</p></form><template #footer><button class="button secondary" :disabled="busy" @click="open=false">Annuler</button><button class="button primary" :disabled="busy||!form.user_id||!form.permissions.length" type="submit" form="api-proposal">{{busy?'Enregistrement…':'Soumettre la proposition'}}</button></template></AppModal><AppModal :model-value="!!ending" title="Terminer cette affectation ?" :busy="busy" @update:model-value="ending=null"><form id="end-assignment" class="form-body correction-form" @submit.prevent="end"><p v-if="dialogError" class="alert error" role="alert">{{dialogError}}</p><p>{{ending?.name}} · {{ending?.scope}}</p><label>Motif obligatoire<textarea v-model="endReason" required maxlength="2000" rows="4"/></label></form><template #footer><button class="button secondary" :disabled="busy" @click="ending=null">Annuler</button><button class="button danger" :disabled="busy" form="end-assignment" type="submit">Confirmer le retrait</button></template></AppModal></section></template>
